import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Enum and Option-Like Fields in AL","description":"","frontmatter":{},"headers":[],"relativePath":"tables-fields-and-business-data/enums-and-option-like-fields.md","filePath":"tables-fields-and-business-data/enums-and-option-like-fields.md"}`),a={name:`tables-fields-and-business-data/enums-and-option-like-fields.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="enum-and-option-like-fields-in-al" tabindex="-1">Enum and Option-Like Fields in AL <a class="header-anchor" href="#enum-and-option-like-fields-in-al" aria-label="Permalink to “Enum and Option-Like Fields in AL”">​</a></h1><p>So far, our <code>Course</code> table has fields such as <code>Course Name</code>, <code>Description</code>, and <code>Price</code>. These fields accept values of types like <code>Text</code> and <code>Decimal</code>.</p><p>But what if we want a field that only accepts values from a predefined set?</p><p>For example, suppose every course must have a status:</p><ul><li>Planned</li><li>In Progress</li><li>Completed</li></ul><p>We don&#39;t want users typing <code>&quot;In progress&quot;</code>, <code>&quot;in progress&quot;</code>, <code>&quot;Progress&quot;</code>, or <code>&quot;Started&quot;</code> and ending up with inconsistent data.</p><p><strong>Enums solve this problem by defining a fixed set of named values.</strong></p><h2 id="what-is-an-enum" tabindex="-1">What is an Enum? <a class="header-anchor" href="#what-is-an-enum" aria-label="Permalink to “What is an Enum?”">​</a></h2><p>An <strong>enum</strong> (enumeration) is a data type that represents a predefined set of named values.</p><p>Think of it as a dropdown whose available choices are defined in code.</p><p>For our Course table, we could define a <code>Course Status</code> enum with these values:</p><table tabindex="0"><thead><tr><th>Enum value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Planned</code></td><td>The course hasn&#39;t started.</td></tr><tr><td><code>InProgress</code></td><td>The course is underway.</td></tr><tr><td><code>Completed</code></td><td>The course has finished.</td></tr></tbody></table><p>Rather than accepting arbitrary text, a field using this enum stores one of the defined choices.</p><p>Enums are separate AL objects, so you can reuse the same enum in multiple fields or tables.</p><h2 id="create-our-first-enum" tabindex="-1">Create our first Enum <a class="header-anchor" href="#create-our-first-enum" aria-label="Permalink to “Create our first Enum”">​</a></h2><p>Let&#39;s implement this using our existing <code>Course</code> table.</p><h3 id="step-1-create-coursestatus-enum-al" tabindex="-1">Step 1: Create <code>CourseStatus.Enum.al</code> <a class="header-anchor" href="#step-1-create-coursestatus-enum-al" aria-label="Permalink to “Step 1: Create CourseStatus.Enum.al”">​</a></h3><p>In VS Code, create a new file named <code>CourseStatus.Enum.al</code>:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>enum 50106 &quot;Course Status&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Extensible = true;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    value(0; Planned)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        Caption = &#39;Planned&#39;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    value(1; InProgress)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        Caption = &#39;In Progress&#39;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    value(2; Completed)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        Caption = &#39;Completed&#39;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s understand the important parts:</p><ul><li><code>enum 50106 &quot;Course Status&quot;</code> declares an enum object with ID <code>50106</code>.</li><li><code>value(0; Planned)</code> defines a possible value, with value ID <code>0</code> and the name <code>Planned</code>.</li><li><code>Caption</code> specifies how the value is displayed to users.</li><li><code>Extensible = true</code> allows other extensions to add values to this enum.</li></ul><p><strong>One important distinction:</strong> The enum&#39;s value ID is not the same thing as its name or caption. The ID identifies the value internally, the name is used in AL code, and the caption is intended for display.</p><p>For example, we can refer to the <code>InProgress</code> value in code, while users see <strong>In Progress</strong>.</p><h3 id="step-2-add-the-enum-to-our-course-table" tabindex="-1">Step 2: Add the Enum to our Course table <a class="header-anchor" href="#step-2-add-the-enum-to-our-course-table" aria-label="Permalink to “Step 2: Add the Enum to our Course table”">​</a></h3><p>Open <code>Course.Table.al</code> and add a fifth field inside the existing <code>fields</code> block:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(5; Status; Enum &quot;Course Status&quot;)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Status&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Our new field uses the enum we just created.</p><p>Conceptually, the Course table now contains:</p><table tabindex="0"><thead><tr><th>Course Code</th><th>Course Name</th><th style="text-align:right;">Price</th><th>Status</th></tr></thead><tbody><tr><td>CS101</td><td>Introduction to Programming</td><td style="text-align:right;">1500</td><td>Planned</td></tr><tr><td>CS102</td><td>Database Fundamentals</td><td style="text-align:right;">2000</td><td>In Progress</td></tr><tr><td>CS103</td><td>Web Development</td><td style="text-align:right;">2500</td><td>Completed</td></tr></tbody></table><p>These are illustrative records. You&#39;ll be able to enter actual data after exposing the field through your page.</p><h3 id="step-3-publish-and-test" tabindex="-1">Step 3: Publish and test <a class="header-anchor" href="#step-3-publish-and-test" aria-label="Permalink to “Step 3: Publish and test”">​</a></h3><p>Save both files and press <strong>F5</strong>.</p><p>Our existing Course List page won&#39;t automatically display the new field. For now, you can add <code>Status</code> to the page&#39;s <code>repeater</code>:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(Status; Rec.Status)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Publish again, open Course List, and try editing a record&#39;s status. Business Central should offer the defined enum choices rather than allowing arbitrary text.</p><h2 id="what-about-option-fields" tabindex="-1">What about <code>Option</code> fields? <a class="header-anchor" href="#what-about-option-fields" aria-label="Permalink to “What about Option fields?”">​</a></h2><p>Before enums became the preferred approach for this kind of extensible design, AL developers commonly used the <code>Option</code> data type.</p><p>For example, an older field might look like this:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(5; Status; Option)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Status&#39;;</span></span>
<span class="line"><span>    OptionMembers = Planned,InProgress,Completed;</span></span>
<span class="line"><span>    OptionCaption = &#39;Planned,In Progress,Completed&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here:</p><ul><li><code>OptionMembers</code> defines the available values.</li><li><code>OptionCaption</code> defines the captions displayed to users.</li></ul><p>The field restricts values to the options specified in its declaration.</p><h3 id="option-vs-enum" tabindex="-1">Option vs Enum <a class="header-anchor" href="#option-vs-enum" aria-label="Permalink to “Option vs Enum”">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th><code>Option</code></th><th><code>Enum</code></th></tr></thead><tbody><tr><td>Defines predefined choices</td><td>Yes</td><td>Yes</td></tr><tr><td>Has named values</td><td>Yes</td><td>Yes</td></tr><tr><td>Can be reused as a separately defined AL object</td><td>No; options are declared on fields or variables</td><td>Yes</td></tr><tr><td>Can be extended by another extension</td><td>Not in the same way</td><td>Yes, when extensibility is enabled</td></tr><tr><td>Preferred for new, extensible designs</td><td>Generally no</td><td>Yes</td></tr></tbody></table><p><strong>The practical rule:</strong> For new AL development, prefer <code>Enum</code> when a field needs a fixed set of named choices. You&#39;ll encounter <code>Option</code> in older code, so it&#39;s worth understanding, but you generally shouldn&#39;t choose it for new fields.</p><h2 id="a-subtle-but-important-detail" tabindex="-1">A subtle but important detail <a class="header-anchor" href="#a-subtle-but-important-detail" aria-label="Permalink to “A subtle but important detail”">​</a></h2><p>An enum field doesn&#39;t necessarily require the user to choose a value explicitly before the record is saved. For example, if the enum&#39;s first value is <code>Planned</code>, a new record may initially have that value as its default.</p><p>If a business rule requires a particular status or transition, you&#39;ll need to implement that rule separately.</p><p>Also, changing an enum&#39;s existing value IDs or removing values after deployment can have data-compatibility implications. Treat deployed enum values as part of your data model.</p><h3 id="official-documentation" tabindex="-1">Official documentation <a class="header-anchor" href="#official-documentation" aria-label="Permalink to “Official documentation”">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-extensible-enums" target="_blank" rel="noreferrer">Enum object — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/option/option-data-type" target="_blank" rel="noreferrer">Option data type — Microsoft Learn</a></li></ul>`,51)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};